def min_day_to_play(n, m, k, offers):
    # Convert the list of offers into a more usable form
    sale_days = [[] for _ in range(n + 1)]
    for d, t in offers:
        sale_days[t].append(d)

    # Sort sale days for each type
    for i in range(1, n + 1):
        sale_days[i].sort()

    # Binary search to find the minimum day
    low, high = 1, 2 * 10**5

    while low < high:
        mid = (low + high) // 2
        if can_buy_all(mid, n, k, sale_days):
            high = mid
        else:
            low = mid + 1

    return low

def can_buy_all(day, n, k, sale_days):
    total_burles = 0
    for i in range(1, n + 1):
        if k[i - 1] > 0:
            # Find the latest sale day for type i before or on the given day
            sale_idx = binary_search(sale_days[i], day)
            if sale_idx >= 0:
                total_burles += k[i - 1] * 1
            else:
                total_burles += k[i - 1] * 2
    return total_burles <= day

def binary_search(arr, x):
    """Returns the largest index in arr where arr[index] <= x or -1 if no such index exists."""
    low, high = 0, len(arr) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] <= x:
            result = mid
            low = mid + 1
        else:
            high = mid - 1
    return result

